INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "A pharmacy began receiving frequent complaints about long wait times. The manager analyzed the busiest hours and realized staffing did not match demand. She adjusted the schedule to add an extra pharmacist during peak hours. Complaints about wait times dropped significantly within a month."}'::jsonb, '{"key_points": ["a pharmacy received complaints about wait times", "the manager found staffing did not match demand", "she added an extra pharmacist at peak hours", "complaints dropped within a month"]}'::jsonb, 46, 0.55, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-000000000012', 1),
('passage_reconstruction', '{"passage": "A retail chain noticed declining sales at one of its stores. Regional managers visited the location and interviewed staff. They discovered the store layout was confusing customers. After redesigning the layout, sales at that location recovered within two months."}'::jsonb, '{"key_points": ["a retail chain noticed declining sales", "managers interviewed staff at the store", "the layout was confusing customers", "sales recovered after a redesign"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-000000000012', 2),
('passage_reconstruction', '{"passage": "Thank you for your feedback regarding the recent changes to our appointment system. We understand this created some confusion for patients this month, and we sincerely apologize. We have updated our instructions and added staff to assist with scheduling questions going forward."}'::jsonb, '{"key_points": ["thanks for feedback about the appointment system", "apologizes for the confusion", "instructions have been updated", "staff were added to help with scheduling"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-000000000012', 3);
