INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "Your clinic has had an increase in patient wait-time complaints. Your manager, Dr. Nilsson, wants ideas for improving the patient experience without hiring more staff. Write an email to her suggesting three ways to achieve this. Your suggestions must come from the following three themes: online check-in, better appointment spacing, a waiting-room update system. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-000000000014', 1),
('email_writing', '{"prompt": "Your store is planning to redesign its layout. Your manager, Mr. Castillo, wants ideas for the new design. Write an email to him suggesting three priorities for the redesign. Your suggestions must come from the following three themes: clearer signage, wider aisles, a more visible checkout area. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-000000000014', 2);
