INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('story_retelling', '{"story": "A pharmacy technician noticed a pattern of prescription errors during busy afternoons. Instead of ignoring it, she suggested a double-check system for that time of day. Her manager approved a trial period. Prescription errors during afternoons dropped to almost zero."}'::jsonb, null, 44, 0.52, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-00000000001a', 1),
('story_retelling', '{"story": "A retail manager noticed customers often left the store without finding what they needed. She rearranged popular items closer to the entrance. She also trained staff to greet customers proactively. Within weeks, customer satisfaction scores improved noticeably."}'::jsonb, null, 42, 0.54, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-00000000001a', 2),
('story_retelling', '{"story": "A nurse noticed that new patients often seemed confused about hospital procedures. She created a simple one-page guide explaining what to expect during their visit. The guide was distributed at check-in. Patient questions at the front desk decreased significantly afterward."}'::jsonb, null, 44, 0.53, 'B2', 'approved', 'exam', 'business', 'd3000000-0000-4000-8000-00000000001a', 3);
